'use client'
import { useState, useEffect, useRef, useCallback } from 'react'

const PRECIO = 10000
const COL_CENTERS = [94.5,187.4,280.2,373.2,466.1,559.0,651.9,744.8,837.7,930.6]
const ROW_CENTERS = [923,955,985,1016,1046,1077,1108,1139,1169,1200]
const TW = 46, TH = 21

const LOGO_NUEVO = 'data:image/png;base64,'
const LOGO_VIEJO = 'data:image/png;base64,'
const FOTO1 = 'data:image/png;base64,'
const FOTO2 = 'data:image/png;base64,'
const FLYER_BG = 'data:image/jpeg;base64,'
const TILDE_IMG = 'data:image/png;base64,'
const SEED_DATA: Record<string,{usuario:string,pago:string,vendio:string}> = {"0": {"usuario": "GONZAEZ ALEYIYO", "pago": "NO PAGO", "vendio": "MAXI"}, "1": {"usuario": "", "pago": "NO PAGO", "vendio": ""}, "2": {"usuario": "CHULA", "pago": "PAGO", "vendio": "MAXI"}, "3": {"usuario": "DAVID", "pago": "NO PAGO", "vendio": "MAXI"}, "4": {"usuario": "MARCELA", "pago": "PAGO", "vendio": "MAXI"}, "5": {"usuario": "CAMILA ALE YIYO", "pago": "NO PAGO", "vendio": "MAXI"}, "6": {"usuario": "CHICHE", "pago": "PAGO", "vendio": "MAXI"}, "7": {"usuario": "ALEXANDER", "pago": "PAGO", "vendio": "MAXI"}, "8": {"usuario": "CHULA", "pago": "PAGO", "vendio": "MAXI"}, "9": {"usuario": "FLOR", "pago": "NO PAGO", "vendio": "VICKY"}, "10": {"usuario": "PABLO", "pago": "PAGO", "vendio": "MAXI"}, "11": {"usuario": "MIMI", "pago": "PAGO", "vendio": "MAXI"}, "12": {"usuario": "OSVALDO", "pago": "PAGO", "vendio": "MAXI"}, "13": {"usuario": "RAUL", "pago": "PAGO", "vendio": "MAXI"}, "14": {"usuario": "PEÑA", "pago": "PAGO", "vendio": "MAXI"}, "15": {"usuario": "ROBERTO", "pago": "PAGO", "vendio": "MAXI"}, "16": {"usuario": "DANIEL", "pago": "PAGO", "vendio": "MAXI"}, "17": {"usuario": "OSVALDO", "pago": "PAGO", "vendio": "MAXI"}, "18": {"usuario": "SILVANA", "pago": "PAGO", "vendio": "MAXI"}, "19": {"usuario": "CHICHE", "pago": "PAGO", "vendio": "MAXI"}, "20": {"usuario": "YIYO", "pago": "PAGO", "vendio": "MAXI"}, "21": {"usuario": "THOMAS", "pago": "PAGO", "vendio": "MAXI"}, "22": {"usuario": "RICARDO", "pago": "PAGO", "vendio": "MAXI"}, "23": {"usuario": "CELINA", "pago": "PAGO", "vendio": "MAXI"}, "24": {"usuario": "ESTEFANIA", "pago": "NO PAGO", "vendio": "ESTEBAN"}, "25": {"usuario": "MARA", "pago": "NO PAGO", "vendio": "MAXI"}, "26": {"usuario": "SEBA", "pago": "PAGO", "vendio": "MAXI"}, "27": {"usuario": "RAUL", "pago": "PAGO", "vendio": "MAXI"}, "28": {"usuario": "CLAUDIO", "pago": "PAGO", "vendio": "MAXI"}, "29": {"usuario": "OSVALDO", "pago": "PAGO", "vendio": "MAXI"}, "30": {"usuario": "KARI", "pago": "PAGO", "vendio": "MAXI"}, "31": {"usuario": "GASTON", "pago": "PAGO", "vendio": "ESTEBAN"}, "32": {"usuario": "ROMINA QUINTE", "pago": "PAGO", "vendio": "MAXI"}, "33": {"usuario": "OSVALDO", "pago": "PAGO", "vendio": "MAXI"}, "35": {"usuario": "CARNICERO ALBERTO", "pago": "PAGO", "vendio": "MAXI"}, "36": {"usuario": "ANI", "pago": "PAGO", "vendio": "MAXI"}, "37": {"usuario": "KARI", "pago": "PAGO", "vendio": "MAXI"}, "41": {"usuario": "JAVIER", "pago": "PAGO", "vendio": "MAXI"}, "42": {"usuario": "ELENA GODOY", "pago": "PAGO", "vendio": "VICKY"}, "44": {"usuario": "JUAN", "pago": "PAGO", "vendio": "MAXI"}, "45": {"usuario": "MAXI", "pago": "PAGO", "vendio": "MAXI"}, "47": {"usuario": "", "pago": "NO PAGO", "vendio": ""}, "48": {"usuario": "JUAN", "pago": "PAGO", "vendio": "MAXI"}, "50": {"usuario": "NICO", "pago": "PAGO", "vendio": "MAXI"}, "51": {"usuario": "PAISA", "pago": "PAGO", "vendio": "MAXI"}, "52": {"usuario": "ROBERTO", "pago": "PAGO", "vendio": "MAXI"}, "55": {"usuario": "MARTIN", "pago": "PAGO", "vendio": "MAXI"}, "56": {"usuario": "LUIS", "pago": "PAGO", "vendio": "MAXI"}, "63": {"usuario": "JAVIER", "pago": "PAGO", "vendio": "MAXI"}, "64": {"usuario": "", "pago": "NO PAGO", "vendio": ""}, "65": {"usuario": "DAVID", "pago": "NO PAGO", "vendio": "MAXI"}, "66": {"usuario": "GASTON", "pago": "PAGO", "vendio": "ESTEBAN"}, "67": {"usuario": "CELINA", "pago": "PAGO", "vendio": "MAXI"}, "68": {"usuario": "", "pago": "NO PAGO", "vendio": ""}, "69": {"usuario": "PEÑA", "pago": "PAGO", "vendio": "MAXI"}, "70": {"usuario": "GERMAN", "pago": "PAGO", "vendio": "MAXI"}, "72": {"usuario": "MATY FUTBOL", "pago": "PAGO", "vendio": "ESTEBAN"}, "74": {"usuario": "SEBASTIAN AVALOS", "pago": "PAGO", "vendio": "ESTEBAN"}, "77": {"usuario": "GASTON", "pago": "PAGO", "vendio": "ESTEBAN"}, "78": {"usuario": "RICARDO", "pago": "PAGO", "vendio": "ESTEBAN"}, "81": {"usuario": "MIMI", "pago": "PAGO", "vendio": "MAXI"}, "82": {"usuario": "ORIANA", "pago": "NO PAGO", "vendio": "VICKY"}, "83": {"usuario": "VICENTE", "pago": "NO PAGO", "vendio": "MAXI"}, "87": {"usuario": "", "pago": "NO PAGO", "vendio": ""}, "88": {"usuario": "EMI", "pago": "NO PAGO", "vendio": "VICKY"}, "90": {"usuario": "SILVIA GODOY", "pago": "PAGO", "vendio": "VICKY"}, "94": {"usuario": "", "pago": "NO PAGO", "vendio": ""}, "95": {"usuario": "NACHO G.", "pago": "NO PAGO", "vendio": "ESTEBAN"}, "96": {"usuario": "MEL", "pago": "NO PAGO", "vendio": "VICKY"}, "99": {"usuario": "OSVALDO", "pago": "PAGO", "vendio": "MAXI"}}


type NumData = { numero: number; usuario: string; pago: string; vendio: string; marcado: boolean }
type Vista = 'menu'|'nueva'|'lista'|'pendientes'|'grilla'|'editar'|'sinDatos'|'talonario'

export default function RifaApp() {
  const [loggedIn, setLoggedIn] = useState(false)
  const [loginUser, setLoginUser] = useState('')
  const [loginPass, setLoginPass] = useState('')
  const [showPass, setShowPass] = useState(false)
  const [recordar, setRecordar] = useState(false)
  const [loginErr, setLoginErr] = useState('')
  const [vista, setVista] = useState<Vista>('menu')
  const [numeros, setNumeros] = useState<NumData[]>([])
  const [loading, setLoading] = useState(false)
  const [searchLista, setSearchLista] = useState('')
  const [nvNumero, setNvNumero] = useState('')
  const [nvUsuario, setNvUsuario] = useState('')
  const [nvPago, setNvPago] = useState('NO PAGO')
  const [nvVendio, setNvVendio] = useState('ESTEBAN')
  const [nvErr, setNvErr] = useState('')
  const [nvOk, setNvOk] = useState(false)
  const [editNum, setEditNum] = useState('')
  const [editUsuario, setEditUsuario] = useState('')
  const [editPago, setEditPago] = useState('NO PAGO')
  const [editVendio, setEditVendio] = useState('ESTEBAN')
  const [editMarcado, setEditMarcado] = useState(true)
  const [editOk, setEditOk] = useState(false)
  const [canvasReady, setCanvasReady] = useState(false)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const flyerRef = useRef<HTMLImageElement|null>(null)
  const tildeRef = useRef<HTMLImageElement|null>(null)

  useEffect(() => {
    const saved = localStorage.getItem('rifa_creds')
    if (saved) {
      try {
        const c = JSON.parse(atob(saved))
        setLoginUser(c.u||''); setLoginPass(c.p||''); setRecordar(true)
      } catch {}
    }
    const f = new Image(); f.src = FLYER_BG; flyerRef.current = f
    const t = new Image(); t.src = TILDE_IMG; tildeRef.current = t
  }, [])

  useEffect(() => {
    const handler = () => { if (vista !== 'menu') { setVista('menu'); history.pushState({},'') } }
    window.addEventListener('popstate', handler)
    return () => window.removeEventListener('popstate', handler)
  }, [vista])

  const irA = (v: Vista) => { setVista(v); history.pushState({}, '') }
  const volverMenu = () => setVista('menu')

  const fetchNumeros = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/numeros')
      const data = await res.json()
      setNumeros(Array.isArray(data) ? data : [])
    } catch { setNumeros([]) }
    setLoading(false)
  }, [])

  const login = () => {
    if (loginUser.trim().toUpperCase()==='VIAJEVELEZ' && loginPass.trim()==='Necochea2026') {
      if (recordar) localStorage.setItem('rifa_creds', btoa(JSON.stringify({u:'VIAJEVELEZ',p:'Necochea2026'})))
      else localStorage.removeItem('rifa_creds')
      setLoggedIn(true); fetchNumeros()
    } else {
      setLoginErr('❌ Usuario o contraseña incorrectos')
      setTimeout(() => setLoginErr(''), 3000)
    }
  }

  useEffect(() => {
    if (!loggedIn) return
    const doSeed = async () => {
      const res = await fetch('/api/numeros')
      const data = await res.json()
      if (Array.isArray(data) && data.length === 0) {
        for (const [num, d] of Object.entries(SEED_DATA)) {
          await fetch('/api/numeros', {
            method: 'POST',
            headers: {'Content-Type':'application/json'},
            body: JSON.stringify({numero:parseInt(num), ...d})
          })
        }
        await fetchNumeros()
      }
    }
    doSeed()
  }, [loggedIn])

  const vendidos = numeros.filter(n => n.marcado)
  const pagados = vendidos.filter(n => n.pago==='PAGO')
  const noPagados = vendidos.filter(n => n.pago!=='PAGO')
  const sinDatos = vendidos.filter(n => !n.usuario||n.usuario==='')
  const pct = vendidos.length
  const getNum = (n: number) => numeros.find(x => x.numero===n && x.marcado)
  const libres = Array.from({length:100},(_,i)=>i).filter(i => !getNum(i))

  const guardarVenta = async () => {
    if (!nvNumero || !nvUsuario.trim()) {
      setNvErr('⚠️ Completá todos los campos')
      setTimeout(() => setNvErr(''), 3000); return
    }
    const res = await fetch('/api/numeros', {
      method: 'POST',
      headers: {'Content-Type':'application/json'},
      body: JSON.stringify({numero:parseInt(nvNumero), usuario:nvUsuario.trim().toUpperCase(), pago:nvPago, vendio:nvVendio})
    })
    if (res.ok) {
      setNvOk(true); await fetchNumeros()
      setTimeout(() => { setNvOk(false); setNvNumero(''); setNvUsuario(''); setNvPago('NO PAGO'); volverMenu() }, 1800)
    }
  }

  const cargarEdit = (n: string) => {
    setEditNum(n)
    const d = numeros.find(x => x.numero===parseInt(n))
    if (d) { setEditUsuario(d.usuario||''); setEditPago(d.pago||'NO PAGO'); setEditVendio(d.vendio||'ESTEBAN'); setEditMarcado(true) }
  }

  const guardarEdicion = async () => {
    await fetch('/api/numero', {
      method: 'PATCH',
      headers: {'Content-Type':'application/json'},
      body: JSON.stringify({numero:parseInt(editNum), usuario:editUsuario.toUpperCase(), pago:editPago, vendio:editVendio, marcado:editMarcado})
    })
    setEditOk(true); await fetchNumeros()
    setTimeout(() => { setEditOk(false); volverMenu() }, 1600)
  }

  const marcarPago = async (n: number) => {
    const d = numeros.find(x => x.numero===n)
    await fetch('/api/numero', {
      method: 'PATCH',
      headers: {'Content-Type':'application/json'},
      body: JSON.stringify({numero:n, usuario:d?.usuario||'', pago:'PAGO', vendio:d?.vendio||'', marcado:true})
    })
    await fetchNumeros()
  }

  const dibujarCanvas = useCallback(() => {
    const canvas = canvasRef.current; if (!canvas) return
    const fImg = flyerRef.current; const tImg = tildeRef.current; if (!fImg||!tImg) return
    setCanvasReady(false)
    const draw = () => {
      canvas.width = fImg.naturalWidth||1024; canvas.height = fImg.naturalHeight||1536
      const ctx = canvas.getContext('2d')!
      ctx.drawImage(fImg, 0, 0)
      vendidos.forEach(n => {
        const row = Math.floor(n.numero/10), col = n.numero%10
        ctx.drawImage(tImg, COL_CENTERS[col]-TW/2, ROW_CENTERS[row]-TH/2, TW, TH)
      })
      setCanvasReady(true)
    }
    if (fImg.complete && fImg.naturalWidth && tImg.complete) draw()
    else { fImg.onload = () => { if(tImg.complete) draw() }; tImg.onload = () => { if(fImg.complete&&fImg.naturalWidth) draw() } }
  }, [vendidos])

  useEffect(() => { if (vista==='talonario') dibujarCanvas() }, [vista, dibujarCanvas])

  const descargar = () => {
    const canvas = canvasRef.current; if (!canvas) return
    const a = document.createElement('a')
    a.download = 'talonario_'+new Date().toLocaleDateString('es-AR').replace(/\//g,'-')+'.png'
    a.href = canvas.toDataURL('image/png'); a.click()
  }

  // Estilos
  const inp = {width:'100%',padding:'11px 14px',border:'2px solid #dde',borderRadius:'10px',fontSize:'1rem',outline:'none',background:'#f8faff',marginTop:'4px'} as React.CSSProperties
  const lbl = {display:'block',fontSize:'.83rem',fontWeight:700,color:'#444',marginTop:'12px'} as React.CSSProperties
  const btnB = {flex:1,padding:'13px',background:'#003580',color:'white',border:'none',borderRadius:'10px',fontSize:'1rem',fontWeight:700,cursor:'pointer'} as React.CSSProperties
  const btnG = {flex:1,padding:'13px',background:'#f0f0f0',color:'#555',border:'none',borderRadius:'10px',fontSize:'1rem',fontWeight:700,cursor:'pointer'} as React.CSSProperties
  const secH = {background:'#003580',color:'white',padding:'11px 12px',display:'flex',alignItems:'center',gap:'10px',position:'sticky',top:0,zIndex:10} as React.CSSProperties
  const backB = {background:'rgba(255,255,255,.2)',border:'none',color:'white',borderRadius:'8px',padding:'6px 12px',cursor:'pointer',fontWeight:700,fontSize:'.85rem'} as React.CSSProperties

  const BtnMenu = ({icon,label,onClick,color='#003580'}: {icon:string,label:string,onClick:()=>void,color?:string}) => (
    <button onClick={onClick} style={{background:'white',border:`2px solid ${color}`,color,borderRadius:'14px',padding:'14px 8px',fontSize:'.82rem',fontWeight:700,cursor:'pointer',display:'flex',flexDirection:'column',alignItems:'center',gap:'5px',touchAction:'manipulation'}}>
      <span style={{fontSize:'1.7rem'}}>{icon}</span>{label}
    </button>
  )

  const Badge = ({type,text}: {type:string,text:string}) => {
    const cols: Record<string,[string,string]> = {pago:['#d4edda','#155724'],nopago:['#fff3cd','#856404'],vendido:['#cfe2ff','#084298'],libre:['#f8d7da','#842029'],sindata:['#ffe0e0','#900']}
    const [bg,fg] = cols[type]||['#eee','#333']
    return <span style={{background:bg,color:fg,padding:'2px 8px',borderRadius:'20px',fontSize:'.72rem',fontWeight:700,display:'inline-block'}}>{text}</span>
  }

  if (!loggedIn) return (
    <div style={{position:'fixed',inset:0,display:'flex',alignItems:'center',justifyContent:'center',background:'linear-gradient(135deg,#003580,#0057b8,#1a6fd4)'}}>
      <div style={{background:'white',borderRadius:'20px',padding:'32px 24px',width:'min(340px,90vw)',textAlign:'center',boxShadow:'0 20px 60px rgba(0,0,0,.4)'}}>
        <div style={{display:'flex',justifyContent:'center',gap:'12px',marginBottom:'14px'}}>
          <img src={LOGO_NUEVO} alt="V" style={{height:'58px'}}/>
          <img src={LOGO_VIEJO} alt="VS" style={{height:'58px'}}/>
        </div>
        <h1 style={{color:'#003580',fontSize:'1.2rem',fontWeight:900,marginBottom:'4px'}}>RIFA BICICLETA FIRE BIRD</h1>
        <p style={{color:'#666',fontSize:'.82rem',marginBottom:'18px'}}>Sur Cup · Necochea 2026</p>
        <input type="text" placeholder="Usuario" value={loginUser} onChange={e=>setLoginUser(e.target.value)}
          onKeyDown={e=>e.key==='Enter'&&login()} style={{...inp,marginBottom:'12px'}}/>
        <div style={{position:'relative',marginBottom:'12px'}}>
          <input type={showPass?'text':'password'} placeholder="Contraseña" value={loginPass}
            onChange={e=>setLoginPass(e.target.value)} onKeyDown={e=>e.key==='Enter'&&login()}
            style={{...inp,paddingRight:'44px',marginTop:0}}/>
          <button onClick={()=>setShowPass(!showPass)} style={{position:'absolute',right:'10px',top:'50%',transform:'translateY(-50%)',background:'none',border:'none',cursor:'pointer',fontSize:'1.2rem',color:'#888'}}>
            {showPass?'🙈':'👁️'}
          </button>
        </div>
        <label style={{display:'flex',alignItems:'center',gap:'8px',fontSize:'.85rem',color:'#555',marginBottom:'16px',cursor:'pointer'}}>
          <input type="checkbox" checked={recordar} onChange={e=>setRecordar(e.target.checked)} style={{accentColor:'#003580'}}/>
          Recordar contraseña
        </label>
        <button onClick={login} style={{...btnB,width:'100%'}}>INGRESAR</button>
        {loginErr && <p style={{color:'#c00',fontSize:'.88rem',marginTop:'10px',fontWeight:700}}>{loginErr}</p>}
      </div>
    </div>
  )

  return (
    <div style={{position:'fixed',inset:0,display:'flex',flexDirection:'column',overflow:'hidden',background:'#e8f0fa'}}>
      {/* HEADER */}
      <div style={{background:'linear-gradient(135deg,#003580,#0057b8)',color:'white',flexShrink:0,boxShadow:'0 3px 12px rgba(0,0,0,.3)'}}>
        <div style={{display:'flex',alignItems:'center',padding:'8px 10px',gap:'6px'}}>
          <div style={{display:'flex',alignItems:'center',gap:'5px',flexShrink:0}}>
            <img src={LOGO_NUEVO} alt="V" style={{height:'38px',objectFit:'contain'}}/>
            <img src={FOTO1} alt="J" style={{height:'50px',borderRadius:'8px',objectFit:'cover',border:'2px solid rgba(255,255,255,.35)'}}/>
          </div>
          <div style={{flex:1,textAlign:'center'}}>
            <h1 style={{fontSize:'.9rem',fontWeight:900,lineHeight:1.2}}>GRAN RIFA<br/>BICICLETA FIRE BIRD</h1>
            <p style={{fontSize:'.65rem',opacity:.85}}>Sur Cup · Necochea 2026</p>
          </div>
          <div style={{display:'flex',alignItems:'center',gap:'5px',flexShrink:0}}>
            <img src={FOTO2} alt="J" style={{height:'50px',borderRadius:'8px',objectFit:'cover',border:'2px solid rgba(255,255,255,.35)'}}/>
            <img src={LOGO_VIEJO} alt="VS" style={{height:'38px',objectFit:'contain'}}/>
          </div>
        </div>
        <div style={{background:'rgba(255,255,255,.15)',padding:'7px 10px'}}>
          <div style={{display:'flex',justifyContent:'space-between',fontSize:'.78rem',fontWeight:700,color:'white',marginBottom:'5px'}}>
            <span>{pct} vendidos</span><span>{100-pct} restan</span>
          </div>
          <div style={{background:'rgba(255,255,255,.25)',borderRadius:'20px',height:'18px',overflow:'hidden'}}>
            <div style={{height:'100%',borderRadius:'20px',background:'linear-gradient(90deg,#f9c74f,#f8961e)',width:`${pct}%`,transition:'width .6s',display:'flex',alignItems:'center',justifyContent:'flex-end',paddingRight:'6px',fontSize:'.7rem',fontWeight:900,color:'#003580',minWidth:'30px'}}>
              {pct}%
            </div>
          </div>
          <div style={{display:'flex',justifyContent:'space-between',marginTop:'5px',fontSize:'.73rem',color:'white'}}>
            <span>💰 Recaudado: <b>${(pagados.length*PRECIO).toLocaleString('es-AR')}</b></span>
            <span>⏳ Pend. cobro: <b>${(noPagados.length*PRECIO).toLocaleString('es-AR')}</b></span>
          </div>
        </div>
      </div>

      {/* CONTENT */}
      <div style={{flex:1,overflowY:'auto',WebkitOverflowScrolling:'touch' as any}}>
        {loading && <p style={{textAlign:'center',padding:'20px',color:'#888'}}>Cargando...</p>}

        {/* MENU */}
        {vista==='menu' && (
          <div style={{padding:'12px'}}>
            <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'10px'}}>
              <BtnMenu icon="➕" label="Nueva Venta" onClick={()=>irA('nueva')} color="#2b9348"/>
              <BtnMenu icon="📋" label="Ver Lista" onClick={()=>irA('lista')}/>
              <BtnMenu icon="⏳" label="Pendientes Pago" onClick={()=>irA('pendientes')} color="#e09000"/>
              <BtnMenu icon="🔢" label="Grilla Números" onClick={()=>irA('grilla')}/>
              <BtnMenu icon="✏️" label="Editar" onClick={()=>irA('editar')} color="#c00"/>
              <BtnMenu icon="⚠️" label={`Sin Datos (${sinDatos.length})`} onClick={()=>irA('sinDatos')}/>
              <button onClick={()=>irA('talonario')} style={{background:'white',border:'2px solid #0077cc',color:'#0077cc',borderRadius:'14px',padding:'14px 8px',fontSize:'.82rem',fontWeight:700,cursor:'pointer',display:'flex',flexDirection:'column',alignItems:'center',gap:'5px',gridColumn:'span 2',touchAction:'manipulation'}}>
                <span style={{fontSize:'1.7rem'}}>🖼️</span>Ver Talonario / Descargar
              </button>
            </div>
            <button onClick={fetchNumeros} style={{width:'100%',marginTop:'10px',padding:'10px',background:'#e8f0fa',border:'2px solid #aac',borderRadius:'10px',color:'#446',fontWeight:700,cursor:'pointer',fontSize:'.82rem'}}>
              🔄 Actualizar datos
            </button>
          </div>
        )}

        {/* NUEVA VENTA */}
        {vista==='nueva' && (
          <>
            <div style={secH}><button style={backB} onClick={volverMenu}>← Volver</button><h2 style={{fontSize:'.95rem',fontWeight:900}}>➕ Nueva Venta</h2></div>
            <div style={{padding:'12px'}}>
              <label style={lbl}>Número vendido</label>
              <select value={nvNumero} onChange={e=>setNvNumero(e.target.value)} style={inp}>
                <option value="">— Seleccioná un número libre —</option>
                {libres.map(n=><option key={n} value={n}>{String(n).padStart(2,'0')}</option>)}
              </select>
              <label style={lbl}>Comprador</label>
              <input type="text" value={nvUsuario} onChange={e=>setNvUsuario(e.target.value.toUpperCase())} placeholder="Nombre del comprador" style={inp}/>
              <label style={lbl}>¿Abonó?</label>
              <div style={{display:'flex',gap:'10px',marginTop:'4px'}}>
                {['PAGO','NO PAGO'].map(v=>(
                  <label key={v} style={{flex:1,display:'flex',alignItems:'center',gap:'6px',background:nvPago===v?'#e8f4ff':'#f0f4ff',borderRadius:'8px',padding:'9px 12px',cursor:'pointer',border:`2px solid ${nvPago===v?'#003580':'transparent'}`,justifyContent:'center'}}>
                    <input type="radio" name="nvPago" value={v} checked={nvPago===v} onChange={()=>setNvPago(v)} style={{accentColor:'#003580'}}/>
                    {v==='PAGO'?'✅ Pagado':'⏳ No pagado'}
                  </label>
                ))}
              </div>
              <label style={lbl}>Cargado por</label>
              <select value={nvVendio} onChange={e=>setNvVendio(e.target.value)} style={inp}>
                {['ESTEBAN','GABI','MAXI','VICKY'].map(v=><option key={v} value={v}>{v.charAt(0)+v.slice(1).toLowerCase()}</option>)}
              </select>
              {nvErr && <p style={{color:'#c00',textAlign:'center',fontWeight:700,marginTop:'8px'}}>{nvErr}</p>}
              {nvOk && <p style={{color:'#2b9348',textAlign:'center',fontWeight:700,marginTop:'8px'}}>✅ Venta registrada</p>}
              <div style={{display:'flex',gap:'10px',marginTop:'16px'}}>
                <button style={btnG} onClick={volverMenu}>Cancelar</button>
                <button style={btnB} onClick={guardarVenta}>Guardar</button>
              </div>
            </div>
          </>
        )}

        {/* LISTA */}
        {vista==='lista' && (
          <>
            <div style={secH}><button style={backB} onClick={volverMenu}>← Volver</button><h2 style={{fontSize:'.95rem',fontWeight:900}}>📋 Lista</h2></div>
            <div style={{padding:'10px 12px',background:'white',borderBottom:'1px solid #e8f0fa'}}>
              <input type="text" placeholder="Buscar número o nombre..." value={searchLista} onChange={e=>setSearchLista(e.target.value.toUpperCase())} style={{...inp,marginTop:0}}/>
            </div>
            <div style={{overflowX:'auto',padding:'0 12px 16px'}}>
              <table style={{width:'100%',borderCollapse:'collapse',fontSize:'.8rem'}}>
                <thead><tr>{['#','Comprador','Estado','Pago','Cargó'].map(h=><th key={h} style={{background:'#003580',color:'white',padding:'9px 7px',textAlign:'left'}}>{h}</th>)}</tr></thead>
                <tbody>
                  {Array.from({length:100},(_,i)=>i)
                    .filter(i=>{ const d=getNum(i); const num=String(i).padStart(2,'0'); if(!searchLista) return true; return num.includes(searchLista)||(d?.usuario||'').includes(searchLista) })
                    .map((i,idx)=>{ const d=getNum(i); const sd=d&&(!d.usuario||d.usuario==='')
                      return <tr key={i} style={{background:idx%2===0?'white':'#f0f5ff'}}>
                        <td style={{padding:'8px 7px',borderBottom:'1px solid #e8f0fa'}}><b>{String(i).padStart(2,'0')}</b></td>
                        <td style={{padding:'8px 7px',borderBottom:'1px solid #e8f0fa'}}>{d?(sd?<Badge type="sindata" text="SIN DATOS"/>:d.usuario):'—'}</td>
                        <td style={{padding:'8px 7px',borderBottom:'1px solid #e8f0fa'}}>{d?<Badge type="vendido" text="Vendido"/>:<Badge type="libre" text="Libre"/>}</td>
                        <td style={{padding:'8px 7px',borderBottom:'1px solid #e8f0fa'}}>{d?(d.pago==='PAGO'?<Badge type="pago" text="✅ Pago"/>:<Badge type="nopago" text="⏳ Pendiente"/>):'—'}</td>
                        <td style={{padding:'8px 7px',borderBottom:'1px solid #e8f0fa'}}>{d?.vendio||'—'}</td>
                      </tr>
                    })}
                </tbody>
              </table>
            </div>
          </>
        )}

        {/* PENDIENTES */}
        {vista==='pendientes' && (
          <>
            <div style={secH}><button style={backB} onClick={volverMenu}>← Volver</button><h2 style={{fontSize:'.95rem',fontWeight:900}}>⏳ Pendientes de Pago</h2></div>
            <div style={{padding:'10px 12px 16px'}}>
              {noPagados.length===0 && <p style={{textAlign:'center',padding:'24px',color:'#2b9348',fontWeight:700}}>¡Sin pendientes! 🎉</p>}
              {noPagados.sort((a,b)=>a.numero-b.numero).map(n=>(
                <div key={n.numero} style={{background:'white',borderRadius:'12px',padding:'12px 14px',marginBottom:'9px',boxShadow:'0 2px 8px rgba(0,0,60,.07)',borderLeft:'4px solid #e09000',display:'flex',alignItems:'center',gap:'10px'}}>
                  <div style={{fontSize:'1.3rem',fontWeight:900,color:'#003580'}}>{String(n.numero).padStart(2,'0')}</div>
                  <div style={{flex:1}}>
                    <p style={{fontWeight:700,fontSize:'.88rem'}}>{n.usuario||'Sin datos'}</p>
                    <p style={{fontSize:'.78rem',color:'#666'}}>Vendido pendiente de pago · Cargó: {n.vendio||'—'}</p>
                  </div>
                  <button onClick={()=>marcarPago(n.numero)} style={{background:'#2b9348',color:'white',border:'none',borderRadius:'8px',padding:'7px 12px',fontWeight:700,cursor:'pointer',fontSize:'.82rem'}}>Cobrado ✅</button>
                </div>
              ))}
            </div>
          </>
        )}

        {/* GRILLA */}
        {vista==='grilla' && (
          <>
            <div style={secH}><button style={backB} onClick={volverMenu}>← Volver</button><h2 style={{fontSize:'.95rem',fontWeight:900}}>🔢 Grilla</h2></div>
            <div style={{padding:'8px 12px',fontSize:'.75rem',display:'flex',gap:'12px',flexWrap:'wrap'}}>
              {[['#003580','Vendido'],['#e00','Sin datos'],['#e8f0fa','Libre']].map(([c,l])=>(
                <span key={l}><span style={{display:'inline-block',width:'12px',height:'12px',background:c,borderRadius:'2px',verticalAlign:'middle',border:c==='#e8f0fa'?'1px solid #ccd':'none'}}/> {l}</span>
              ))}
            </div>
            <div style={{display:'grid',gridTemplateColumns:'repeat(10,1fr)',gap:'3px',padding:'8px 12px'}}>
              {Array.from({length:100},(_,i)=>i).map(i=>{ const d=getNum(i); const sd=d&&(!d.usuario||d.usuario==='')
                return <div key={i} title={d?`${d.usuario||'Sin datos'} | ${d.pago}`:'Libre'}
                  style={{aspectRatio:'1',display:'flex',alignItems:'center',justifyContent:'center',borderRadius:'5px',fontSize:'.7rem',fontWeight:700,background:d?(sd?'#e00':'#003580'):'#e8f0fa',color:d?'white':'#888',border:d?'none':'1px solid #ccd'}}>
                  {String(i).padStart(2,'0')}
                </div>
              })}
            </div>
          </>
        )}

        {/* EDITAR */}
        {vista==='editar' && (
          <>
            <div style={secH}><button style={backB} onClick={volverMenu}>← Volver</button><h2 style={{fontSize:'.95rem',fontWeight:900}}>✏️ Editar</h2></div>
            <div style={{padding:'12px'}}>
              <label style={lbl}>Número a editar</label>
              <select value={editNum} onChange={e=>cargarEdit(e.target.value)} style={inp}>
                <option value="">— Seleccioná —</option>
                {vendidos.sort((a,b)=>a.numero-b.numero).map(n=>(
                  <option key={n.numero} value={n.numero}>{String(n.numero).padStart(2,'0')} — {n.usuario||'Sin datos'}</option>
                ))}
              </select>
              {editNum && (<>
                <label style={lbl}>Comprador</label>
                <input type="text" value={editUsuario} onChange={e=>setEditUsuario(e.target.value.toUpperCase())} style={inp}/>
                <label style={lbl}>¿Abonó?</label>
                <div style={{display:'flex',gap:'10px',marginTop:'4px'}}>
                  {['PAGO','NO PAGO'].map(v=>(
                    <label key={v} style={{flex:1,display:'flex',alignItems:'center',gap:'6px',background:editPago===v?'#e8f4ff':'#f0f4ff',borderRadius:'8px',padding:'9px 12px',cursor:'pointer',border:`2px solid ${editPago===v?'#003580':'transparent'}`,justifyContent:'center'}}>
                      <input type="radio" name="editPago" value={v} checked={editPago===v} onChange={()=>setEditPago(v)} style={{accentColor:'#003580'}}/>
                      {v==='PAGO'?'✅ Pagado':'⏳ No pagado'}
                    </label>
                  ))}
                </div>
                <label style={lbl}>Cargado por</label>
                <select value={editVendio} onChange={e=>setEditVendio(e.target.value)} style={inp}>
                  {['ESTEBAN','GABI','MAXI','VICKY'].map(v=><option key={v} value={v}>{v.charAt(0)+v.slice(1).toLowerCase()}</option>)}
                </select>
                <label style={lbl}>¿Marcado?</label>
                <div style={{display:'flex',gap:'10px',marginTop:'4px'}}>
                  {([true,false] as boolean[]).map(v=>(
                    <label key={String(v)} style={{flex:1,display:'flex',alignItems:'center',gap:'6px',background:editMarcado===v?'#e8f4ff':'#f0f4ff',borderRadius:'8px',padding:'9px 12px',cursor:'pointer',border:`2px solid ${editMarcado===v?'#003580':'transparent'}`,justifyContent:'center'}}>
                      <input type="radio" name="editMarcado" checked={editMarcado===v} onChange={()=>setEditMarcado(v)} style={{accentColor:'#003580'}}/>
                      {v?'✅ Sí':'❌ Desmarcar'}
                    </label>
                  ))}
                </div>
                {editOk && <p style={{color:'#2b9348',textAlign:'center',fontWeight:700,marginTop:'8px'}}>✅ Guardado</p>}
                <div style={{display:'flex',gap:'10px',marginTop:'16px'}}>
                  <button style={btnG} onClick={volverMenu}>Cancelar</button>
                  <button style={btnB} onClick={guardarEdicion}>Guardar cambios</button>
                </div>
              </>)}
            </div>
          </>
        )}

        {/* SIN DATOS */}
        {vista==='sinDatos' && (
          <>
            <div style={secH}><button style={backB} onClick={volverMenu}>← Volver</button><h2 style={{fontSize:'.95rem',fontWeight:900}}>⚠️ Sin Datos</h2></div>
            <div style={{background:'#ffe0e0',borderLeft:'4px solid #c00',padding:'10px 14px',margin:'8px 12px',borderRadius:'8px',fontSize:'.82rem',color:'#900',fontWeight:700}}>
              Números vendidos sin comprador registrado.
            </div>
            <div style={{padding:'0 12px 16px'}}>
              {sinDatos.length===0 && <p style={{textAlign:'center',padding:'24px',color:'#2b9348',fontWeight:700}}>✅ Todos tienen datos</p>}
              {sinDatos.sort((a,b)=>a.numero-b.numero).map(n=>(
                <div key={n.numero} style={{background:'white',borderRadius:'12px',padding:'12px 14px',marginBottom:'9px',boxShadow:'0 2px 8px rgba(0,0,60,.07)',borderLeft:'4px solid #c00',display:'flex',alignItems:'center',gap:'10px'}}>
                  <div style={{fontSize:'1.3rem',fontWeight:900,color:'#c00'}}>{String(n.numero).padStart(2,'0')}</div>
                  <div style={{flex:1}}>
                    <p style={{fontWeight:700,fontSize:'.88rem',color:'#c00'}}>Sin comprador</p>
                    <p style={{fontSize:'.78rem',color:'#666'}}>Cargó: {n.vendio||'—'}</p>
                  </div>
                  <button onClick={()=>{ cargarEdit(String(n.numero)); irA('editar') }} style={{background:'#003580',color:'white',border:'none',borderRadius:'8px',padding:'7px 12px',fontWeight:700,cursor:'pointer',fontSize:'.82rem'}}>Completar</button>
                </div>
              ))}
            </div>
          </>
        )}

        {/* TALONARIO */}
        {vista==='talonario' && (
          <>
            <div style={secH}><button style={backB} onClick={volverMenu}>← Volver</button><h2 style={{fontSize:'.95rem',fontWeight:900}}>🖼️ Talonario</h2></div>
            <div style={{padding:'10px 12px',textAlign:'center'}}>
              {!canvasReady && <p style={{color:'#888',fontSize:'.85rem',marginBottom:'8px'}}>Generando imagen...</p>}
              <canvas ref={canvasRef} style={{maxWidth:'100%',borderRadius:'10px',boxShadow:'0 4px 16px rgba(0,0,60,.2)'}}/>
            </div>
            <button onClick={descargar} style={{display:'block',width:'calc(100% - 24px)',margin:'0 12px 14px',padding:'14px',background:'linear-gradient(90deg,#003580,#0057b8)',color:'white',border:'none',borderRadius:'12px',fontSize:'1rem',fontWeight:700,cursor:'pointer'}}>
              ⬇️ Descargar PNG
            </button>
          </>
        )}

      </div>
    </div>
  )
}
